(function(){
  // Attempt to load the real prefixfree library by fetching its minified source and executing it.
  // This fallback tries cdnjs; if that fails (e.g., CDN blocked), it will log the failure.
  var cdn = 'https://cdnjs.cloudflare.com/ajax/libs/prefixfree/1.0.7/prefixfree.min.js';
  function loadCode(code) {
    try {
      var s = document.createElement('script');
      s.type = 'text/javascript';
      s.text = code;
      document.head.appendChild(s);
      console.info('prefixfree: loaded code via fallback fetch.');
    } catch (e) {
      console.warn('prefixfree: fallback load failed', e);
    }
  }
  // Try to fetch the library text and evaluate it.
  if (window.fetch) {
    fetch(cdn, {mode: 'cors'})
      .then(function(res){ if (!res.ok) throw new Error('Network response not ok'); return res.text(); })
      .then(function(code){ loadCode(code); })
      .catch(function(err){ console.warn('prefixfree: could not fetch from CDN in fallback.', err); });
  } else {
    // Older browsers: create script tag to CDN (last resort)
    var s = document.createElement('script');
    s.src = cdn;
    s.crossOrigin = 'anonymous';
    s.onload = function(){ console.info('prefixfree: loaded via script element fallback'); };
    s.onerror = function(e){ console.warn('prefixfree: fallback script element failed to load', e); };
    document.head.appendChild(s);
  }
})();
